    public static StackPane of(String name, double size) {
        SVGPath p = new SVGPath();
        String d = PATHS.get(name);
        if (d == null) throw new IllegalArgumentException("Icona sconosciuta: " + name);
        p.setContent(d);
        p.getStyleClass().add("rp-icon");
        double s = size / 24.0;
        p.setScaleX(s);
        p.setScaleY(s);
        StackPane box = new StackPane(p);
        box.setMinSize(size, size);
        box.setPrefSize(size, size);
        box.setMaxSize(size, size);
        return box;
    }

    public static StackPane of(String name) {
        return of(name, 16);
    }
